(function(){(function(){"use strict";document.addEventListener(`click`,e=>{let t=e.target.closest(`button[data-confirm-submit]`);t&&t.form&&!t.disabled&&t.dataset.confirmed!==`true`&&typeof window.confirmDialog==`function`&&(e.preventDefault(),window.confirmDialog({...t.dataset,callback:e=>{if(e){t.dataset.confirmed=`true`;try{t.form.requestSubmit(t)}finally{delete t.dataset.confirmed}}}}))})})()})();
